export function visualWorkspace({make,toast}){
 const dialog=make('dialog','visual-settings'),heading=make('h2','','Workspace y pantallas'),status=make('p'),list=make('div');dialog.append(heading,status,list);document.body.append(dialog);
 const call=a=>window.argosDesktop.capability({tool:'workspace',arguments:{action:'visual',...a}});
 async function run(a){try{const result=await call(a);if(!result.ok)throw Error(result.error||result.message||'No confirmado');await load()}catch(e){status.textContent=e.message}}
 function button(label,fn,parent=dialog){const b=make('button','',label);b.onclick=fn;parent.append(b);return b}
 async function load(){const data=await window.argosDesktop.capability({tool:'workspace',arguments:{action:'inspect'}}),v=data.visual;status.textContent=`${v.backend||'Preparando'} · ${v.displays?.length||0} pantallas · Recuperación: abrir ARGOS${v.recovery?.shortcut?' / '+v.recovery.shortcut:''}. Voz solo si la escucha está activa.`;list.replaceChildren();for(const d of v.displays||[])list.append(make('p','',`${d.ordinal} · ${d.label} · ${d.bounds.width} × ${d.bounds.height} · escala ${d.scale}${d.primary?' · principal':''}`));for(const s of v.surfaces||[]){const row=make('div','surface-row');row.append(make('strong','',s.ref?.path||'Superficie disponible'));const select=make('select');select.setAttribute('aria-label','Destino de '+s.id);for(const d of v.displays){const o=make('option','',`${d.ordinal} · ${d.label}`);o.value=d.key;select.append(o)}select.value=s.display;row.append(select);button('Mover',()=>run({operation:'move',id:s.id,display:select.value}),row);button('Solo esta',()=>run({operation:'only',id:s.id}),row);button('Cerrar',()=>run({operation:'close',id:s.id}),row);if(s.error)row.append(make('p','',s.error));list.append(row)}}
 button('Actualizar',()=>run({operation:'inspect'}));button('Usar todas las pantallas',()=>run({operation:'distribute'}));button('Solo pantalla principal',()=>run({operation:'primary'}));button('Ocultar workspace',async()=>{dialog.close();try{await call({operation:'hide'})}catch(e){toast(e.message)}});button('Cerrar',()=>dialog.close());
 return async()=>{dialog.showModal();try{await run({operation:'inspect'})}catch(e){status.textContent=e.message}};
}
